<?php require __DIR__.'/_layout_start.php'; ?><h1>Campus - Iscrizioni</h1><table><thead><tr><th>Evento</th><th>Partecipante</th><th>Contatti</th><th>Azienda</th><th>Stato</th><th>Presenza</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= htmlspecialchars($r['event_title'],ENT_QUOTES,'UTF-8') ?></strong><br><span class="badge"><?= htmlspecialchars(strtoupper($r['audience']),ENT_QUOTES,'UTF-8') ?></span></td><td><?= htmlspecialchars($r['first_name'].' '.$r['last_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($r['email'],ENT_QUOTES,'UTF-8') ?><?= !empty($r['phone'])?'<br>'.htmlspecialchars($r['phone'],ENT_QUOTES,'UTF-8'):'' ?></td><td><?= htmlspecialchars((string)($r['cat_company']?:$r['company']),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($r['status'],ENT_QUOTES,'UTF-8') ?></td><td><?= $r['attended']===null?'—':((int)$r['attended']?'Sì':'No') ?></td><td><form method="post" action="/admin/campus/registrations/update"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status"><option value="registered" <?= $r['status']==='registered'?'selected':'' ?>>registered</option><option value="confirmed" <?= $r['status']==='confirmed'?'selected':'' ?>>confirmed</option><option value="waitlist" <?= $r['status']==='waitlist'?'selected':'' ?>>waitlist</option><option value="cancelled" <?= $r['status']==='cancelled'?'selected':'' ?>>cancelled</option></select><select name="attended"><option value="">—</option><option value="1" <?= $r['attended']!==null&&(int)$r['attended']===1?'selected':'' ?>>Presente</option><option value="0" <?= $r['attended']!==null&&(int)$r['attended']===0?'selected':'' ?>>Assente</option></select><button class="btn" type="submit">Salva</button></form></td></tr><?php endforeach;?></tbody></table><?php require __DIR__.'/_layout_end.php'; ?>
